<script setup lang="ts">
import { Head, Link, router, usePage } from '@inertiajs/vue3';
import AppShell from '../Components/AppShell.vue';
import Errors from '../Components/Errors.vue';
import { type Transaction, money } from '../types';
type Event = {id:number;status:string;payload:{merchant:string;amount_decimal:string;observed_at:string;transaction_at:string|null};currency:string|null;currency_source:string;connection_name:string;account_id:number;transaction:Transaction|null;candidates:Transaction[]};
defineProps<{events:{data:Event[];prev_page_url:string|null;next_page_url:string|null}}>();
const page=usePage();
function attach(event:Event,target:Transaction) {router.post(`/wallet-matches/${event.id}/attach`,{transaction_id:target.id,confirmed:true});}
</script>
<template><AppShell><Head title="Wallet receipt matching"/><Link href="/integrations/wallet" class="back-link">← Wallet settings</Link><section class="page-heading"><div><h1>Wallet &amp; receipt matches</h1><p class="muted">Matching, receipt availability, review, and bank reconciliation are separate states.</p></div></section><Errors :errors="page.props.errors"/>
<p class="review-notice">Automatic matches require one unique candidate, equal exact totals, known compatible currencies, the same normalized merchant, and date/time evidence. Known accounts must agree. Date-only receipts require the same known account and calendar date. Unknown accounts require an actual event timestamp and receipt time within five minutes. Unknown receipt timezones use the event’s supplied offset. No windows are silently expanded. Check tips, authorizations, refunds, and split payments manually.</p>
<p v-if="!events.data.length" class="muted">No real Wallet events yet. Test events appear in connection history and do not affect spending.</p>
<article v-for="event in events.data" :key="event.id" class="edit-panel wallet-card"><div class="section-heading"><h2>{{ event.payload.merchant }}</h2><span class="pill">{{ event.status }}</span></div><p>{{ money({amount:event.payload.amount_decimal,currency:event.currency}) }} · {{ event.connection_name }} · Account #{{ event.account_id }}</p><p class="small muted">Currency source: {{ event.currency_source }}<br/>Observed: {{ event.payload.observed_at }}<br/>Transaction timestamp: {{ event.payload.transaction_at || 'Not supplied — observation time is not bank-confirmed' }}</p><p v-if="event.transaction" class="small">Current purchase: {{ event.transaction.merchant }} · {{ money(event.transaction) }} · {{ event.transaction.purchase_date }} {{ event.transaction.purchase_time }} · {{ event.transaction.account?.nickname || 'Unknown account' }}</p><p v-if="event.transaction"><Link :href="`/transactions/${event.transaction.id}`">Open purchase #{{ event.transaction.id }} ↗</Link> · {{ event.transaction.receipt ? 'Receipt available' : 'No receipt yet' }} · {{ event.transaction.review_status }} · Bank-unreconciled</p>
<template v-if="event.status==='matched'"><button class="button secondary" @click="router.post(`/wallet-matches/${event.id}/separate`)">Undo attachment / count separately</button><p class="small muted">Original Wallet purchase, receipt, extraction history, and corrections are retained.</p></template>
<template v-else-if="event.status==='needs_account'"><p>No purchase has been created yet. <Link href="/integrations/wallet">Assign the Wallet identifier to an account →</Link></p></template><template v-else><div v-for="candidate in event.candidates" :key="candidate.id" class="review-notice"><h3>{{ candidate.merchant }} · {{ money(candidate) }}</h3><p>{{ candidate.purchase_date }} {{ candidate.purchase_time || '(date only)' }} · {{ candidate.account?.nickname || 'Unknown payment account' }}</p><p class="small">Source: receipt #{{ candidate.receipt?.id }}. Compare the original image and source values before confirming.</p><div class="wallet-actions"><Link :href="`/transactions/${candidate.id}`" class="button secondary">Inspect receipt</Link><button class="button primary" @click="attach(event,candidate)">I confirm these are the same purchase</button></div></div><p v-if="!event.candidates.length" class="small muted">No compatible receipt candidates. Correct any merchant, amount, currency, date, or account errors on the purchases, then retry matching.</p><div class="wallet-actions"><button class="button secondary" @click="router.post(`/wallet-matches/${event.id}/separate`)">Confirm separate purchase</button><button v-if="event.status!=='separate'" class="text-button" @click="router.post(`/wallet-matches/${event.id}/retry`)">Retry matching</button></div></template></article>
<div class="wallet-actions"><Link v-if="events.prev_page_url" :href="events.prev_page_url">← Previous</Link><Link v-if="events.next_page_url" :href="events.next_page_url">Next →</Link></div></AppShell></template>
